import sys
from datetime import datetime, timedelta

def time_to_minutes(time_str):
    h, m = map(int, time_str.split(':'))
    return h * 60 + m

def minutes_to_time(minutes):
    h = minutes // 60
    m = minutes % 60
    return f"{h:02d}:{m:02d}"

def overlaps(b1, b2):
    return b1[3] < b2[4] and b2[3] < b1[4]

def main():
    bookings = []
    room_booking = {}  # room -> list of (bid, start_min, end_min)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        cmd = parts[0]
        if cmd == "book":
            bid = parts[1]
            room = parts[2]
            day = parts[3]
            start_str = parts[4]
            end_str = parts[5]

            # Parse times
            try:
                start_min = time_to_minutes(start_str)
                end_min = time_to_minutes(end_str)
            except ValueError:
                print(f"INVALID {bid}")
                continue

            if end_min <= start_min:
                print(f"INVALID {bid}")
                continue

            # Check for overlap with active bookings
            overlaps_found = False
            other = None
            for other_bid, other_start_min, other_end_min in room_booking.get(
                room, []
            ):
                if overlaps((start_min, end_min), (other_start_min, other_end_min)):
                    overlaps_found = True
                    if other is None or other_start_min < start_min:
                        other = other_bid

            if overlaps_found:
                print(f"REJECT {bid} {other}")
            else:
                # Add booking
                bookings.append((bid, room, day, start_str, end_str))
                room_booking.setdefault(room, []).append((bid, start_min, end_min))
                print(f"ACCEPT {bid}")
        elif cmd == "cancel":
            bid = parts[1]
            found = False
            new_bookings = []
            for b in bookings:
                if b[0] != bid:
                    new_bookings.append(b)
                else:
                    found = True
            bookings = new_bookings
            if not found:
                print(f"UNKNOWN {bid}")
            else:
                # Remove from room_booking as well
                room = bookings[bookings.index((bid, _, _, _, _))][1]
                room_bookings = room_booking.get(room, [])
                room_bookings = [
                    (bid2, s, e)
                    for (bid2, s, e) in room_bookings
                    if bid2 != bid
                ]
                room_booking[room] = room_bookings
                print(f"CANCELLED {bid}")

    # Summary
    room_summary = {}
    for room, bookings_list in room_booking.items():
        total_minutes = 0
        for _, start, end in bookings_list:
            total_minutes += end - start
        room_summary[room] = {"count": len(bookings_list), "total_minutes": total_minutes}

    sorted_rooms = sorted(room_summary.keys())

    for room in sorted_rooms:
        count = room_summary[room]["count"]
        total = room_summary[room]["total_minutes"]
        hours = total // 60
        minutes = total % 60
        print(f"{room} {count} {minutes_to_time(hours * 60 + minutes)}")

if __name__ == "__main__":
    main()
